/* Fire FX (v71): PolyOne "Fire Effects" (Unity asset pack Jeter downloaded Nov 27; assets/fire/). Its 6x6 fire flipbook
   (alpha only, tinted per particle like the Unity prefabs) drawn as additive camera-facing billboards. Atlas cell 35 = the pack's glow sprite.
   Palettes: orange = brazier torches, blue = wraith bolts, red = The Creature's bolts / slams. */
var FIRE_TEX="data:image/png;base64,";
var FFX={p:null,tried:0,tex:null,ready:0,P:[],Q:[],buf:null,arr:null,MAX:1800,
  PAL:{orange:[[1,.9,.66],[1,.64,.16],[.96,.34,.05],[.45,.09,.02]],blue:[[.4,.65,1],[.12,.32,1],[.22,.07,.95],[.06,.01,.32]],red:[[1,.5,.32],[1,.16,.06],[.72,.02,.03],[.26,0,.02]]},
  GLOW:{orange:[1,.5,.14],blue:[.15,.32,1],red:[1,.08,.04]}};
function ffxCol(pal,t){const K=FFX.PAL[pal]||FFX.PAL.orange,f=Math.min(2.999,Math.max(0,t)*3),i=f|0,u=f-i,a=K[i],b=K[i+1];return [a[0]+(b[0]-a[0])*u,a[1]+(b[1]-a[1])*u,a[2]+(b[2]-a[2])*u];}
// o: {grow:end size multiplier, k:brightness, rise:upward accel, drag, rot:max start roll}
function ffxEmit(x,y,z,vx,vy,vz,life,size,pal,o){if(FFX.P.length>=FFX.MAX)return;o=o||{};const r=o.rot===undefined?3.14:o.rot;
  FFX.P.push({x,y,z,vx,vy,vz,t:0,life,s:size,g:o.grow||1.5,pal,k:o.k||1,rise:o.rise||0,drag:o.drag||0,rot:(Math.random()*2-1)*r,rv:(Math.random()*2-1)*(o.spin||.6)});}
function ffxPuff(x,y,z,pal,n,size,spd){for(let i=0;i<n;i++){const a=Math.random()*6.283,u=Math.random()*2-1,s=Math.sqrt(1-u*u)*(spd||2)*(.4+Math.random()*.6);
  ffxEmit(x,y,z,Math.cos(a)*s,u*(spd||2)*.5+.6,Math.sin(a)*s,.45+Math.random()*.35,(size||1.2)*(.7+Math.random()*.5),pal,{grow:1.8,rise:1.5,drag:2.5,k:.45});}}
function ffxBoltPal(b){return b.src==='spitter'?'blue':b.src==='boss'?'red':null;}
function ffxUpdate(dt){if(!(dt>0))return;const L=FFX.P;
  for(const p of L){p.t+=dt;const d=Math.max(0,1-p.drag*dt);p.vx*=d;p.vz*=d;p.vy=p.vy*d+p.rise*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;p.rot+=p.rv*dt;}
  FFX.P=L.filter(p=>p.t<p.life);
  // braziers: a steady column of flame puffs
  for(const f of G.flames){const pal=f.red?'red':'orange';f._fa=(f._fa||0)+dt*16;while(f._fa>=1){f._fa--;
    ffxEmit(f.x+(Math.random()-.5)*.34,f.y-.12,f.z+(Math.random()-.5)*.34,(Math.random()-.5)*.25,.9+Math.random()*.8,(Math.random()-.5)*.25,.75+Math.random()*.45,.9+Math.random()*.4,pal,{grow:1.3,rise:.6,drag:.6,rot:.35,spin:.4,k:.38});}}
  // enemy bolts: fiery trail
  for(const b of G.eb){const pal=ffxBoltPal(b);if(!pal)continue;const big=pal==='red';b._fa=(b._fa||0)+dt*(big?26:24);while(b._fa>=1){b._fa--;
    const j=big?.18:.12;ffxEmit(b.x+(Math.random()-.5)*j,b.y+(Math.random()-.5)*j,b.z+(Math.random()-.5)*j,-b.vx*.08+(Math.random()-.5)*.6,-b.vy*.08+(Math.random()-.5)*.6+.3,-b.vz*.08+(Math.random()-.5)*.6,
      (big?.34:.28)+Math.random()*.12,(big?1.25:.95)*(.8+Math.random()*.4),pal,{grow:1.6,rise:1,drag:1.5,k:big?.22:.16});}}}
function ffxLoad(){FFX.tried=1;try{const sh=(t,src)=>{const o=gl.createShader(t);gl.shaderSource(o,src);gl.compileShader(o);if(!gl.getShaderParameter(o,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(o));return o;};
  const p=gl.createProgram();
  gl.attachShader(p,sh(gl.VERTEX_SHADER,'attribute vec3 aP;attribute vec2 aU;attribute vec4 aC;uniform mat4 uVP;varying vec2 vU;varying vec4 vC;void main(){vU=aU;vC=aC;gl_Position=uVP*vec4(aP,1.);}'));
  gl.attachShader(p,sh(gl.FRAGMENT_SHADER,'precision mediump float;uniform sampler2D uT;varying vec2 vU;varying vec4 vC;void main(){float a=texture2D(uT,vU).r*vC.a;gl_FragColor=vec4(vC.rgb*a,0.);}'));
  gl.bindAttribLocation(p,0,'aP');gl.bindAttribLocation(p,1,'aU');gl.bindAttribLocation(p,2,'aC');gl.linkProgram(p);
  if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(p));FFX.p=p;FFX.u={vp:gl.getUniformLocation(p,'uVP'),t:gl.getUniformLocation(p,'uT')};
  FFX.buf=gl.createBuffer();FFX.arr=new Float32Array((FFX.MAX+64)*6*9);
  const im=new Image();im.onload=()=>{const t=gl.createTexture();gl.activeTexture(gl.TEXTURE7);gl.bindTexture(gl.TEXTURE_2D,t);
    gl.texImage2D(gl.TEXTURE_2D,0,gl.LUMINANCE,gl.LUMINANCE,gl.UNSIGNED_BYTE,im);gl.generateMipmap(gl.TEXTURE_2D);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR_MIPMAP_LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
    gl.activeTexture(gl.TEXTURE0);FFX.tex=t;FFX.ready=1;};im.src=FIRE_TEX;}catch(err){console.error(err);FFX.p=null;}}
function ffxDraw(){if(!FFX.tried)ffxLoad();if(!FFX.p||!FFX.ready)return;
  const A_=FFX.arr,rx=VW[0],ry=VW[4],rz=VW[8],ux=VW[1],uy=VW[5],uz=VW[9],cx=CAMW[0],cy=CAMW[1],cz=CAMW[2];let n=0;const cap=FFX.MAX+60;
  const quad=(x,y,z,s,rot,fr,r,g,b,a)=>{if(n>=cap)return;const d=Math.hypot(x-cx,y-cy,z-cz);a*=1-Math.min(1,Math.max(0,(d-10)/75))*.85;if(a<=.004)return;
    const c=Math.cos(rot)*s*.5,sn=Math.sin(rot)*s*.5,Rx=rx*c+ux*sn,Ry=ry*c+uy*sn,Rz=rz*c+uz*sn,Ux=ux*c-rx*sn,Uy=uy*c-ry*sn,Uz=uz*c-rz*sn;
    const u0=(fr%6)/6,v0=((fr/6)|0)/6,u1=u0+1/6,v1=v0+1/6;let o=n*54;
    const V=(sx,sy,u,v)=>{A_[o++]=x+Rx*sx+Ux*sy;A_[o++]=y+Ry*sx+Uy*sy;A_[o++]=z+Rz*sx+Uz*sy;A_[o++]=u;A_[o++]=v;A_[o++]=r;A_[o++]=g;A_[o++]=b;A_[o++]=a;};
    V(-1,-1,u0,v1);V(1,-1,u1,v1);V(1,1,u1,v0);V(-1,-1,u0,v1);V(1,1,u1,v0);V(-1,1,u0,v0);n++;};
  const T=G.time;
  for(const f of G.flames){const pal=f.red?'red':'orange',c=FFX.GLOW[pal],k=.8+.12*Math.sin(T*13+f.x)+.08*Math.sin(T*31+f.z);
    quad(f.x,f.y+.35,f.z,3.4*k,0,35,c[0],c[1],c[2],.28);quad(f.x,f.y+.02,f.z,1,T*.7,10+((T*20+f.x*7)|0)%6,1,.8,.5,.35);}
  for(const b of G.eb){const pal=ffxBoltPal(b);if(!pal)continue;const c=FFX.GLOW[pal],big=pal==='red',k=.9+.15*Math.sin(T*24+b.x);
    quad(b.x,b.y,b.z,(big?2.6:2)*k,0,35,c[0],c[1],c[2],big?.38:.3);const h=ffxCol(pal,.12);quad(b.x,b.y,b.z,(big?1.5:1.15)*k,T*5+b.z,8+((T*24+b.x*5)|0)%8,h[0],h[1],h[2],big?.45:.35);
    quad(b.x,b.y,b.z,(big?.7:.5),0,35,1,1,1,.15);}
  for(const p of FFX.P){const t=p.t/p.life,c=ffxCol(p.pal,t),fi=t<.08?t/.08:1;quad(p.x,p.y,p.z,p.s*(1+(p.g-1)*t),p.rot,Math.min(34,(t*35)|0),c[0],c[1],c[2],p.k*fi);}
  if(!n)return;const pm=PP.main;gl.useProgram(FFX.p);gl.uniformMatrix4fv(FFX.u.vp,false,VP);gl.activeTexture(gl.TEXTURE7);gl.bindTexture(gl.TEXTURE_2D,FFX.tex);gl.uniform1i(FFX.u.t,7);
  const at=[A.p,A.n,A.c,A.t];for(const a of at)gl.disableVertexAttribArray(a);
  gl.bindBuffer(gl.ARRAY_BUFFER,FFX.buf);gl.bufferData(gl.ARRAY_BUFFER,A_.subarray(0,n*54),gl.DYNAMIC_DRAW);
  for(let i=0;i<3;i++)gl.enableVertexAttribArray(i);gl.vertexAttribPointer(0,3,gl.FLOAT,false,36,0);gl.vertexAttribPointer(1,2,gl.FLOAT,false,36,12);gl.vertexAttribPointer(2,4,gl.FLOAT,false,36,20);
  gl.enable(gl.BLEND);gl.blendFuncSeparate(gl.ONE,gl.ONE,gl.ZERO,gl.ONE);gl.depthMask(false);gl.drawArrays(gl.TRIANGLES,0,n*6);
  gl.depthMask(true);gl.disable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);for(let i=0;i<3;i++)gl.disableVertexAttribArray(i);for(const a of at)gl.enableVertexAttribArray(a);
  gl.activeTexture(gl.TEXTURE0);gl.useProgram(pm);curMesh=null;}
